# RetrievalService.py
import requests
import json

class RetrievalService:
    def __init__(self, model):
        self.model = model

    def retrieve_policy_evidence(self, question):
        response = requests.post(
            "http://backend:8000/api/upload",
            json={"question": question, "model": "Qwen 2.5"}
        )
        if response.status_code == 200:
            return response.json()
        else:
            return {"error": "Failed to retrieve policy evidence"}
```

